"""Strict JSON envelope rules for the control-plane entry point.

The contract fixes the accepted text: no BOM, only the four JSON whitespace
characters, no trailing JSON, no duplicate keys, no non-finite numbers, at most
64 container levels (strings contribute none), integer tokens no longer than
4300 digits and an input of at most 24 MiB.  Anything else is a whole-request
error, never a partial result.
"""
import json
import math
import re

__all__ = ['Invalid', 'decode', 'MAX_INPUT_BYTES', 'MAX_DEPTH', 'MAX_INTEGER_DIGITS']

MAX_INPUT_BYTES = 24 * 1024 * 1024
MAX_DEPTH = 64
MAX_INTEGER_DIGITS = 4300
MAX_JOBS = 4

# Structural characters only.  A single character class keeps the scanner in
# linear time and, unlike a repeated alternation inside one pattern, does not
# make CPython's sre allocate a mark per iteration on a 24 MiB body.
_STRUCTURAL = re.compile(r'["{}\[\]]')
_QUOTE_OR_ESCAPE = re.compile(r'["\\]')


class Invalid(ValueError):
    """Whole-request JSON or bounds failure."""


def check_nesting(text):
    """Count container levels, skipping string contents entirely.

    Every object or array is one level, the request object itself is level 1 and
    strings (including escaped brackets and quotes) contribute none.  An
    unbalanced or unterminated document is reported here or by the decoder; both
    are whole-request errors.
    """
    depth = 0
    position = 0
    structural = _STRUCTURAL.search
    quote_or_escape = _QUOTE_OR_ESCAPE.search
    while True:
        found = structural(text, position)
        if found is None:
            break
        marker = found.group(0)
        position = found.end()
        if marker == '"':
            while True:
                stop = quote_or_escape(text, position)
                if stop is None:
                    return              # unterminated string: the decoder rejects
                if text[stop.start()] == '\\':
                    position = stop.end() + 1
                    continue
                position = stop.end()
                break
            continue
        if marker == '{' or marker == '[':
            depth += 1
            if depth > MAX_DEPTH:
                raise Invalid('nesting')
        else:
            depth -= 1
            if depth < 0:
                raise Invalid('nesting')


def _unique(pairs):
    result = {}
    for key, value in pairs:
        if key in result:
            raise Invalid('duplicate key')
        result[key] = value
    return result


def _float(token):
    value = float(token)
    if not math.isfinite(value):
        raise Invalid('non-finite number')
    return value


def _constant(token):
    raise Invalid('non-finite token')


def _load(data):
    if data[:1] == b'\xef\xbb\xbf':
        raise Invalid('byte order mark')
    if len(data) > MAX_INPUT_BYTES:
        raise Invalid('input size')
    text = data.decode('utf-8')          # invalid UTF-8 is a whole-request error
    check_nesting(text)
    return json.loads(text, object_pairs_hook=_unique, parse_constant=_constant,
                      parse_float=_float)


def decode(data):
    """Return the validated list of job objects from raw request bytes."""
    try:
        request = _load(data)
    except Invalid:
        raise
    except Exception:
        raise Invalid('json')
    if type(request) is not dict or set(request) != {'jobs'}:
        raise Invalid('envelope')
    jobs = request['jobs']
    if type(jobs) is not list or len(jobs) > MAX_JOBS:
        raise Invalid('jobs')
    return jobs
